command:
$ErrorActionPreference='Stop'
$taskRepo='E:\AI\projects\agent-control-room'
$taskProposal='E:\AI\projects\uoink\checkouts\Yoink-library\_scratch\control-room-command-provenance02'
$taskProof='E:\AI\projects\uoink\checkouts\Yoink-library\_scratch\control-room-command-provenance02-root'
$taskRestore=@()
foreach($taskRel in @('src/agents/gemini.ts','test/gemini-command-provenance.test.mjs')){
  $taskSource=Join-Path $taskProposal $taskRel; $taskDest=Join-Path $taskRepo $taskRel
  $taskExpected=[IO.File]::ReadAllBytes($taskSource); $taskActual=[IO.File]::ReadAllBytes($taskDest)
  if([Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($taskExpected)) -ne [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($taskActual))){
    $taskUTF8=[Text.UTF8Encoding]::new($false,$true)
    if($taskUTF8.GetString($taskExpected).Replace("`r`n","`n") -cne $taskUTF8.GetString($taskActual).Replace("`r`n","`n")){throw 'Non-newline difference'}
    $taskRestore+=@{path=$taskDest;raw=$taskExpected}
  }
}
foreach($taskRow in $taskRestore){[IO.File]::WriteAllBytes($taskRow.path,$taskRow.raw)}
$taskPins=@()
foreach($taskRel in @('src/agents/gemini.ts','test/gemini-command-provenance.test.mjs')){$taskPins+=@{path=$taskRel;sha256=(Get-FileHash -LiteralPath (Join-Path $taskRepo $taskRel) -Algorithm SHA256).Hash.ToLowerInvariant()}}
$taskPins | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $taskProof 'pre-check-pins.json') -Encoding utf8
Remove-Item Env:NODE_OPTIONS -ErrorAction SilentlyContinue
Remove-Item Env:NODE_PATH -ErrorAction SilentlyContinue
& 'C:\Program Files\nodejs\node.exe' --import tsx --test --test-reporter=tap test/gemini-completion.test.mjs test/gemini-command-provenance.test.mjs 1> (Join-Path $taskProof 'checkout-test.stdout.log') 2> (Join-Path $taskProof 'checkout-test.stderr.log')
$taskExit=$global:LASTEXITCODE
[ordered]@{native_exit=$taskExit;newline_only_restored=$taskRestore.Count;command='node --import tsx --test --test-reporter=tap test/gemini-completion.test.mjs test/gemini-command-provenance.test.mjs'} | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $taskProof 'checkout-test-exit.json') -Encoding utf8
Get-Content -LiteralPath (Join-Path $taskProof 'checkout-test.stdout.log')
Get-Content -LiteralPath (Join-Path $taskProof 'checkout-test.stderr.log')
exit $taskExit
